// === Tab: mySketch ===
//Code by Aaron Reuland.
//For the #wccChallenge on the theme of "draggable".
//Just a quick sketch made while on vacation. Drag the little emitter nodes
//around to form subtle patterns.


var emitters = []
var rings = []
var colors = ["#cb417f", "#e05ca4", "#edc0dd", "#deae94", "#cbf7c2", "#2b6860", "#1c0c0e"]

var md

function setup() {
	createCanvas(windowWidth, windowHeight);
	md = max(width, height)
	background(0);
	let pos1 = createVector(width / 3, height / 2)
	let pos2 = createVector(width - width / 3, height / 2)
	let pos3 = createVector(width / 2, height / 2)

	emitters.push(new emitter(pos1, 1))
	emitters.push(new emitter(pos2, 2))
	emitters.push(new emitter(pos3, 3))
}

function draw() {
	for (i = rings.length - 1; i >= 0; i--) {
		rings[i].expand();
		rings[i].drift();
		rings[i].done();
	}
	for (let e of emitters) {
		e.emit();
	}
}

class emitter {
	constructor(pos, i) {
		this.pos = pos;
		this.i = i
		this.d = 20
		this.draggable = false
	}

	emit() {
		if (frameCount % 5 == 0) {
			rings.push(new ring(this.pos, this.i))
		}
		fill(0)
		circle(this.pos.x, this.pos.y, this.d)

	}

	draggable() {

	}
}

class ring {
	constructor(pos, i) {
		this.pos = pos
		this.d = 1
		this.color = colorMixer(i, colors)
		this.acc = 0.02
		this.speed = 0
	}

	expand() {
		this.speed += this.acc
		this.d += this.speed
		stroke(this.color)
		strokeWeight(2)
		noFill()
		ellipse(this.pos.x, this.pos.y, this.d)
	}

	drift() {

	}

	done() {
		if (this.d > (md * 2)) {
			let index = rings.indexOf(this)
			rings.splice(index, 1)
		}
	}
}

function colorMixer(ind, colorArray) {
	let c = noise(ind * 4, frameCount / 250) * colorArray.length
	let c1 = floor(c)
	let c2 = floor(c + 1) % colorArray.length
	let color1 = colorArray[c1]
	let color2 = colorArray[c2]
	let mix = fract(c)
	let coloring = color(spectral.mix(color1, color2, mix))
	return coloring
}




function mousePressed() {

	for (let i = 0; i < emitters.length; i++) {
		let emit = emitters[i]
		if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > emit.pos.x - emit.d / 2 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < emit.pos.x + emit.d / 2 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < emit.pos.y + emit.d / 2 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > emit.pos.y - emit.d / 2) {
			emit.draggable = true
		}
	}
}


function mouseDragged() {
	for (let i = 0; i < emitters.length; i++) {
		var emit = emitters[i]
		if (emit.draggable == true) {
			emit.pos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
		}
	}
}

function mouseReleased() {
	for (let i = 0; i < emitters.length; i++) {
		var emit = emitters[i]
		if (emit.draggable == true) {
			emit.draggable = false
		}
	}

}
